WITH completed_orders AS MATERIALIZED (SELECT o.id,o.customer_id,o.created_at FROM orders o WHERE lower(o.status)='completed' AND o.created_at::date>=DATE '2024-01-01'), captured AS MATERIALIZED (SELECT co.* FROM completed_orders co WHERE EXISTS (SELECT 1 FROM payments p WHERE p.order_id=co.id AND p.status='captured')), qualifying AS (SELECT DISTINCT co.customer_id FROM completed_orders co JOIN order_items oi ON oi.order_id=co.id JOIN products p ON p.id=oi.product_id JOIN product_suppliers ps ON ps.product_id=p.id JOIN suppliers s ON s.id=ps.supplier_id JOIN shipments sh ON sh.order_id=co.id WHERE p.active AND s.risk_tier>=4 AND (sh.delivered_at IS NULL OR sh.delivered_at>sh.shipped_at+INTERVAL '10 days')), cap_agg AS (SELECT customer_id,count(*) AS n FROM captured GROUP BY customer_id), item_agg AS (SELECT x.customer_id,sum((oi.quantity-COALESCE(r.quantity,0))*oi.unit_price) AS v FROM captured x JOIN order_items oi ON oi.order_id=x.id LEFT JOIN returns r ON r.order_id=oi.order_id AND r.line_no=oi.line_no GROUP BY x.customer_id), promo_agg AS (SELECT co.customer_id,sum(op.discount_amount) AS v FROM completed_orders co JOIN order_promotions op ON op.order_id=co.id JOIN promotions pr ON pr.id=op.promotion_id WHERE pr.active GROUP BY co.customer_id), late_agg AS (SELECT co.customer_id,count(*) AS n FROM completed_orders co JOIN shipments sh ON sh.order_id=co.id WHERE sh.delivered_at IS NULL OR sh.delivered_at>sh.shipped_at+INTERVAL '10 days' GROUP BY co.customer_id), risky_agg AS (SELECT co.customer_id,count(DISTINCT ps.supplier_id) AS n FROM completed_orders co JOIN order_items oi ON oi.order_id=co.id JOIN product_suppliers ps ON ps.product_id=oi.product_id JOIN suppliers s ON s.id=ps.supplier_id WHERE s.risk_tier>=4 GROUP BY co.customer_id), last_agg AS (SELECT customer_id,max(created_at) AS t FROM completed_orders GROUP BY customer_id) SELECT c.id AS customer_id,c.region,c.segment,COALESCE(ca.n,0) AS captured_order_count,COALESCE(ia.v,0)::numeric(20,2) AS net_item_revenue,COALESCE(pa.v,0)::numeric(18,2) AS active_promotion_discount,COALESCE(la.n,0) AS late_shipment_count,COALESCE(ra.n,0) AS risky_supplier_count,le.t AS last_completed_at FROM customers c JOIN qualifying q ON q.customer_id=c.id LEFT JOIN cap_agg ca ON ca.customer_id=c.id LEFT JOIN item_agg ia ON ia.customer_id=c.id LEFT JOIN promo_agg pa ON pa.customer_id=c.id LEFT JOIN late_agg la ON la.customer_id=c.id LEFT JOIN risky_agg ra ON ra.customer_id=c.id LEFT JOIN last_agg le ON le.customer_id=c.id WHERE c.active;